// Turns an n8n error into a short message you can read on your phone.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const d = $input.item.json;
const wf = d.workflow?.name || 'Unknown workflow';
const node = d.execution?.lastNodeExecuted || d.trigger?.error?.node?.name || 'unknown step';
const msg = d.execution?.error?.message || d.trigger?.error?.message || 'No error message available';

const text = (
  '🚨 ' + esc(wf) + ' stopped working\n' +
  'Step: ' + esc(node) + '\n' +
  'Problem: ' + esc(String(msg).slice(0, 600)) + '\n\n' +
  'Common causes: Anthropic key invalid or out of credit, Google login expired (reconnect the Gmail credential), model name retired.\n' +
  (d.execution?.url ? 'Details: ' + esc(d.execution.url) : '')
).slice(0, 3800);

return { json: { text } };
